insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_13_v1'
from (values
('127.95.d.1.A',2,'In a safety culture, who is responsible for jobsite safety?','["Everyone on the site", "Only the inspector", "Only the owner", "Only the newest worker"]'::jsonb,0,'A safety culture means all workers share responsibility.','original'),
('127.95.d.1.A',3,'A crew where workers stop unsafe tasks and look out for each other is showing a:','["Loose budget", "Strong safety culture", "Slow schedule", "Weak reputation"]'::jsonb,1,'Shared values and habits make a safety culture.','original'),
('127.95.d.1.B',3,'Why is a safety culture especially important in the construction crafts?','["Sites are always indoors", "Hazards never change", "Work involves heights, heavy loads, and powered tools", "Tools are always lightweight"]'::jsonb,2,'Construction hazards are many and serious.','original'),
('127.95.d.1.B',4,'A contractor with a strong safety culture will usually see fewer:','["Blueprints", "Deliveries", "Customers", "Injuries and lost workdays"]'::jsonb,3,'Safety reduces injuries and downtime.','original'),
('127.95.d.1.C',3,'OSHA stands for:','["Occupational Safety and Health Administration", "Organized Site Housing Agency", "Office of Skilled Home Architecture", "Official Safety and Hazard Association"]'::jsonb,0,'OSHA is the federal workplace safety agency.','original'),
('127.95.d.1.C',4,'One thing OSHA does on construction sites is:','["Hire the crew", "Set and enforce safety standards through inspections", "Draw the blueprints", "Supply the lumber"]'::jsonb,1,'OSHA inspects and issues citations.','original'),
('127.95.d.1.D',3,'OSHA generally requires fall protection for construction work at or above:','["1 foot", "2 feet", "6 feet", "20 feet"]'::jsonb,2,'Six feet is the construction trigger height.','original'),
('127.95.d.1.D',4,'A safe way to use an extension ladder is to set it so the base is one foot out for every:','["20 feet of height", "1 foot of height", "10 feet of height", "4 feet of height"]'::jsonb,3,'The 4-to-1 rule gives a safe angle.','original'),
('127.95.d.1.E',3,'Safety glasses are worn on a jobsite to protect the:','["Eyes", "Knees", "Ears", "Elbows"]'::jsonb,0,'Eye protection stops flying debris.','original'),
('127.95.d.1.E',4,'Before each use, a worker should inspect PPE such as a harness for:','["Color choice", "Cuts, fraying, or damage", "Brand name", "Logo size"]'::jsonb,1,'Damaged PPE may fail.','original'),
('127.95.d.1.F',3,'Before drilling into a wall, a worker should consider that the wall may contain:','["Only sunlight", "Only air", "Live electrical wiring", "Only paint"]'::jsonb,2,'Hidden wiring is a shock hazard.','original'),
('127.95.d.1.F',4,'Lockout/tagout is used to make sure equipment cannot be:','["Moved by hand", "Painted", "Delivered", "Energized while someone is working on it"]'::jsonb,3,'It protects workers from unexpected startup.','original'),
('127.95.d.1.G',3,'A Safety Data Sheet (SDS) is used to learn about:','["The hazards and safe use of a product", "The supplier''s holidays", "The paint color", "The price of a product"]'::jsonb,0,'SDS lists hazards, first aid, and handling.','original'),
('127.95.d.1.G',4,'Where must SDS binders be kept on a jobsite?','["In the owner''s home", "Where workers can get to them during their shifts", "Locked in an office off site", "In a truck far away"]'::jsonb,1,'Access must be quick, especially in emergencies.','original'),
('127.95.d.2.A',3,'Most jobsite accidents are caused by:','["Proper training", "Good planning", "Unsafe acts and unsafe conditions", "Clear walkways"]'::jsonb,2,'Both behaviors and conditions cause accidents.','original'),
('127.95.d.2.A',4,'Rushing a job and skipping steps is an example of an:','["Engineering control", "Safe condition", "Code requirement", "Unsafe act"]'::jsonb,3,'Unsafe acts come from human choices.','original'),
('127.95.d.2.B',3,'Besides medical bills, an accident can also cost a company:','["Lost time, higher insurance, and delays", "Lower taxes", "Free advertising", "Faster schedules"]'::jsonb,0,'Indirect costs add up.','original'),
('127.95.d.2.B',4,'Indirect costs of accidents are costs that:','["Never occur", "Are not billed directly but still hurt the business", "Are paid by the customer", "Are always covered by insurance"]'::jsonb,1,'Hidden costs include lost productivity.','original'),
('127.95.d.2.C',3,'Hazard recognition means being able to:','["Ignore warnings", "Order materials", "Spot dangerous conditions before someone is hurt", "Fix injuries"]'::jsonb,2,'Recognizing hazards allows prevention.','original'),
('127.95.d.2.C',4,'A worker walking a site at the start of a shift and noting hazards is practicing:','["Estimating", "Scheduling", "Layout", "Hazard recognition"]'::jsonb,3,'Walk-throughs help find hazards early.','original'),
('127.95.d.2.D',3,'A struck-by hazard occurs when a worker is hit by:','["A moving or falling object", "A phone call", "A memo", "A cold breeze"]'::jsonb,0,'Falling tools and swinging loads strike workers.','original'),
('127.95.d.2.D',4,'Wearing a hard hat helps protect against which hazard?','["Heat only", "Struck-by", "Chemical splash only", "Noise only"]'::jsonb,1,'Hard hats absorb impacts from above.','original'),
('127.95.d.2.E',3,'A caught-in-between hazard exists when a worker can be:','["Left waiting", "Sent home early", "Squeezed or crushed between objects", "Given extra pay"]'::jsonb,2,'Examples include trench cave-ins and machinery pinch points.','original'),
('127.95.d.2.E',4,'Which situation is a caught-in-between hazard?','["Sweeping a floor", "Reading a plan", "Carrying a tape measure", "Working in an unprotected deep trench"]'::jsonb,3,'Trench walls can collapse and bury workers.','original'),
('127.95.d.2.F',3,'An example of a hazardous material on a jobsite is:','["Asbestos-containing insulation", "A plastic ruler", "A paper cup", "A clean towel"]'::jsonb,0,'Asbestos fibers harm the lungs.','original'),
('127.95.d.2.F',4,'Besides falls and struck-by hazards, workers face electrocution hazards such as:','["Quiet rooms", "Contact with overhead power lines", "Warm weather", "Soft flooring"]'::jsonb,1,'Power lines can carry deadly voltage.','original'),
('127.95.d.2.G',3,'Hazard communication (HazCom) makes sure workers are told about:','["The owner''s vacation", "Next week''s lunch", "The chemical hazards they may be exposed to", "The weather forecast"]'::jsonb,2,'HazCom requires labels, SDS, and training.','original'),
('127.95.d.2.G',4,'A HazCom container label must identify the:','["Crew size", "Store hours", "Delivery driver", "Product and its hazards"]'::jsonb,3,'Labels warn of dangers.','original'),
('127.95.d.3.A',3,'A carpenter has 48 boards and uses 17. How many remain?','["31", "65", "29", "41"]'::jsonb,0,'48 - 17 = 31.','original'),
('127.95.d.3.A',4,'A crew installs 18 sheets of drywall per room in 7 rooms. How many sheets are installed?','["144", "126", "25", "108"]'::jsonb,1,'18 x 7 = 126.','original'),
('127.95.d.3.B',3,'What is 1/2 + 1/4 of an inch?','["2/6 inch", "1 inch", "3/4 inch", "1/8 inch"]'::jsonb,2,'1/2 = 2/4; 2/4 + 1/4 = 3/4.','original'),
('127.95.d.3.B',4,'A board 5/8 inch thick is planed down by 1/8 inch. What is the new thickness?','["6/8 inch", "1/4 inch", "3/4 inch", "1/2 inch"]'::jsonb,3,'5/8 - 1/8 = 4/8 = 1/2.','original'),
('127.95.d.3.C',3,'A pipe is 2.5 feet long. Another is 1.75 feet. What is their total length?','["4.25 feet", "4.75 feet", "3.75 feet", "3.25 feet"]'::jsonb,0,'2.5 + 1.75 = 4.25.','original'),
('127.95.d.3.C',4,'Nails cost $0.12 each. What do 25 nails cost?','["$12.00", "$3.00", "$2.50", "$0.30"]'::jsonb,1,'0.12 x 25 = 3.00.','original'),
('127.95.d.3.D',3,'The decimal 0.25 is the same as what percentage?','["250 percent", "2.5 percent", "25 percent", "0.25 percent"]'::jsonb,2,'Multiply by 100.','original'),
('127.95.d.3.D',4,'A 15 percent tax rate is written as which decimal?','["1.5", "15.0", "0.015", "0.15"]'::jsonb,3,'Divide the percent by 100.','original'),
('127.95.d.3.E',3,'The fraction 3/4 equals which decimal?','["0.75", "3.4", "0.43", "0.34"]'::jsonb,0,'3 divided by 4 = 0.75.','original'),
('127.95.d.3.E',4,'The decimal 0.125 is the same as which fraction?','["1/12", "1/8", "1/5", "1/4"]'::jsonb,1,'0.125 = 125/1000 = 1/8.','original'),
('127.95.d.4.A',3,'On a standard tape measure, the smallest tick marks usually show:','["Feet", "Yards", "16ths of an inch", "Half inches"]'::jsonb,2,'Most tapes mark sixteenths.','original'),
('127.95.d.4.A',4,'An architect''s scale is used to:','["Level a wall", "Cut metal", "Weigh lumber", "Measure lines on drawings at a reduced size"]'::jsonb,3,'Scales let you read dimensions from a drawing.','original'),
('127.95.d.4.B',3,'The metric system is based on units of:','["Ten", "Five", "Sixteen", "Twelve"]'::jsonb,0,'It is a base-10 system.','original'),
('127.95.d.4.B',4,'The metric system matters in construction because many products and plans:','["Never use metric", "Are made or specified in metric units", "Are always in yards", "Only use feet"]'::jsonb,1,'Global products often use metric.','original'),
('127.95.d.4.C',3,'Which metric unit measures length?','["Celsius", "Gram", "Meter", "Liter"]'::jsonb,2,'The meter is the base unit of length.','original'),
('127.95.d.4.C',4,'Which metric unit measures volume of liquid?','["Kilogram", "Newton", "Meter", "Liter"]'::jsonb,3,'Liters measure volume.','original'),
('127.95.d.4.D',3,'A common shape used when laying out a room''s floor is the:','["Rectangle", "Star", "Spiral", "Heart"]'::jsonb,0,'Most rooms are rectangular.','original'),
('127.95.d.4.D',4,'A triangle is used in roof framing because it is:','["Always weak", "A very rigid shape", "Easy to bend", "Flexible"]'::jsonb,1,'Triangles resist deformation.','original'),
('127.95.d.5.A',3,'A claw hammer is mainly used to:','["Weld steel", "Cut pipe", "Drive and pull nails", "Measure"]'::jsonb,2,'The claw pulls nails.','original'),
('127.95.d.5.A',4,'A tool used to mark a straight line over a long distance is a:','["Plumb bob", "Pipe wrench", "Wire stripper", "Chalk line"]'::jsonb,3,'Snapped chalk marks straight lines.','original'),
('127.95.d.5.B',3,'Before using a hammer, a worker should check that the:','["Handle is not cracked and the head is tight", "Price tag is attached", "Color is bright", "Brand is famous"]'::jsonb,0,'A loose head can fly off.','original'),
('127.95.d.5.B',4,'A mushroomed chisel head is unsafe because pieces can:','["Make it lighter", "Chip off and strike the user", "Sharpen the blade", "Make it quieter"]'::jsonb,1,'Damaged heads should be dressed or replaced.','original'),
('127.95.d.5.C',3,'When using a utility knife, cut:','["Toward your legs", "With the blade fully extended always", "Away from your body", "Toward your hand"]'::jsonb,2,'Cutting away avoids injury.','original'),
('127.95.d.5.C',4,'A handsaw cuts best when you:','["Force it hard", "Twist it", "Cut fast and loose", "Let the saw do the work with smooth strokes"]'::jsonb,3,'Proper technique is safer and cleaner.','original'),
('127.95.d.6.A',3,'A tool powered by electricity and used to drive screws is a:','["Cordless drill/driver", "Hand plane", "Level", "Chalk line"]'::jsonb,0,'Drill/drivers are common powered hand tools.','original'),
('127.95.d.6.A',4,'A circular saw is a powered hand tool used to:','["Drive nails by hand", "Make straight cuts in boards and sheet goods", "Mix mortar", "Measure angles"]'::jsonb,1,'It has a rotating blade.','original'),
('127.95.d.6.B',3,'Before changing a blade on a corded saw, you should:','["Remove the guard permanently", "Turn it faster", "Unplug it", "Hold the trigger"]'::jsonb,2,'Disconnect power first.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_13_v1'
from (values
('127.95.d.6.B',4,'When using a power saw, keep the cord:','["Over the blade", "Under the board", "Wrapped around your arm", "Clear of the cutting path"]'::jsonb,3,'A cut cord is a shock hazard.','original'),
('127.95.d.6.C',3,'To maintain a power tool, you should regularly:','["Clean it and check the cord and guards", "Soak it in water", "Paint the motor", "Remove the safety switch"]'::jsonb,0,'Maintenance extends life and safety.','original'),
('127.95.d.6.C',4,'A power tool with a damaged cord should be:','["Used outdoors only", "Taken out of service until repaired", "Taped and used", "Used carefully"]'::jsonb,1,'Damaged cords are dangerous.','original'),
('127.95.d.7.A',3,'On a drawing, a dimension of 10''-6" means:','["10 inches 6 feet", "10.6 feet", "10 feet 6 inches", "106 feet"]'::jsonb,2,'Feet and inches are separated by a dash.','original'),
('127.95.d.7.A',4,'Use dimensions on a drawing instead of measuring the drawing because:','["Rulers are banned", "Dimensions are random", "Measuring is illegal", "Prints may be scaled or distorted"]'::jsonb,3,'Written dimensions are the authority.','original'),
('127.95.d.7.B',3,'The term ''footing'' in construction refers to the:','["Base that supports a foundation wall", "Window trim", "Doorknob", "Roof peak"]'::jsonb,0,'Footings spread loads into soil.','original'),
('127.95.d.7.B',4,'A ''stud'' in wall framing is a:','["Door handle", "Vertical framing member", "Nail gun", "Insulation roll"]'::jsonb,1,'Studs make up the wall frame.','original'),
('127.95.d.7.C',3,'The title block on a drawing gives:','["The weather", "The tool list", "The project name, sheet number, and date", "Pay rates"]'::jsonb,2,'It identifies the sheet.','original'),
('127.95.d.7.C',4,'A north arrow on a site plan shows:','["The roof pitch", "Soil depth", "Wind speed", "Orientation of the site"]'::jsonb,3,'It helps position the building.','original'),
('127.95.d.7.D',3,'On drawings, symbols are explained in the:','["Legend or symbol key", "Invoice", "Weather report", "Phone book"]'::jsonb,0,'Always check the legend.','original'),
('127.95.d.7.D',4,'A dashed line on a plan often represents:','["The north point", "A hidden or future item", "A dimension", "A person"]'::jsonb,1,'Hidden lines show items out of view.','original'),
('127.95.d.7.E',3,'To relate a drawing to the jobsite, a builder uses:','["Rumors", "Colors", "Dimensions and reference points", "Guesswork"]'::jsonb,2,'Layout transfers plan to site.','original'),
('127.95.d.7.E',4,'A grid line labeled ''B'' on the plan helps crews find:','["The weather", "The owner", "The bank", "A specific column or wall line on site"]'::jsonb,3,'Grid lines locate features.','original'),
('127.95.d.7.F',3,'A drawing showing a building from the front is a(n):','["Elevation", "Schedule", "Plan", "Section"]'::jsonb,0,'Elevations show vertical faces.','original'),
('127.95.d.7.F',4,'A drawing that shows the layout of a floor from above is a(n):','["Detail", "Plan", "Elevation", "Section"]'::jsonb,1,'Plans are overhead views.','original'),
('127.95.d.8.A',3,'When reading written instructions for installing a product, a worker should:','["Change the order", "Ignore warnings", "Follow the steps in order", "Skip to the end"]'::jsonb,2,'Order often matters.','original'),
('127.95.d.8.A',4,'A change order in writing tells the crew about:','["Their breaks", "The weather forecast", "Their hours only", "A modification to the original work"]'::jsonb,3,'Written changes must be followed.','original'),
('127.95.d.8.B',3,'After a supervisor gives verbal instructions, a worker should:','["Repeat the key points to confirm them", "Do something else", "Walk away silently", "Guess"]'::jsonb,0,'Confirming prevents errors.','original'),
('127.95.d.8.B',4,'If you don''t understand a spoken instruction, the best response is to:','["Pretend you understood", "Ask for clarification", "Wait to be fired", "Guess"]'::jsonb,1,'Questions avoid mistakes.','original'),
('127.95.d.8.C',3,'Good communication on a crew is clear, polite, and:','["Vague", "Hidden", "Complete", "Rude"]'::jsonb,2,'Complete messages avoid confusion.','original'),
('127.95.d.8.C',4,'A short, accurate daily note about work completed is an example of effective:','["Guessing", "Verbal gossip", "Silent work", "Written communication"]'::jsonb,3,'Writing creates records.','original'),
('127.95.d.8.D',3,'Using a phone on a jobsite should be done:','["Safely and professionally", "On ladders carelessly", "While operating saws", "While driving equipment"]'::jsonb,0,'Distraction causes injuries.','original'),
('127.95.d.8.D',4,'A professional text to a supervisor about a delay should be:','["Unrelated", "Brief, clear, and respectful", "Angry", "Full of slang"]'::jsonb,1,'Professionalism matters in all media.','original'),
('127.95.d.9.A',3,'In material handling, a load is any:','["Idea", "Empty room", "Object being lifted, carried, or moved", "Tape measure only"]'::jsonb,2,'Loads can be heavy or awkward.','original'),
('127.95.d.9.A',4,'The weight of a load matters because it affects the:','["Mood of the crew", "Temperature", "Color of paint", "Method and equipment needed to move it safely"]'::jsonb,3,'Heavier loads need aids.','original'),
('127.95.d.9.B',3,'A pre-task plan for moving a load should identify the:','["Route, hazards, and help needed", "Favorite music", "Brand of boots", "Lunch menu"]'::jsonb,0,'Planning prevents accidents.','original'),
('127.95.d.9.B',4,'Before moving a heavy bundle of pipe, you should first:','["Lift alone", "Plan the path and clear obstacles", "Lift quickly", "Run with it"]'::jsonb,1,'Preparation is part of safe handling.','original'),
('127.95.d.9.C',3,'To lift safely, keep your back straight and lift with your:','["Arms only", "Back", "Legs", "Neck"]'::jsonb,2,'Legs are stronger than the back.','original'),
('127.95.d.9.C',4,'When two workers carry a long plank, they should:','["Race", "Lift at different times", "Drop it", "Communicate and lift together"]'::jsonb,3,'Coordination avoids injuries.','original'),
('127.95.d.9.D',3,'To move a heavy load across a flat site, a good choice is a:','["Hand truck or cart", "Clipboard", "Tape measure", "Pencil"]'::jsonb,0,'Mechanical aids reduce strain.','original'),
('127.95.d.9.D',4,'A load that is too heavy for one person should be moved with:','["Jerking motions", "A team or mechanical equipment", "Running", "Brute force alone"]'::jsonb,1,'Equipment keeps workers safe.','original'),
('127.95.d.9.E',3,'Wear gloves when handling rough lumber to prevent:','["Sunburn", "Boredom", "Splinters and cuts", "Thirst"]'::jsonb,2,'Gloves protect hands.','original'),
('127.95.d.9.E',4,'A common material-handling hazard is a:','["Soft cushion", "Clear floor", "Wide aisle", "Pinch point between a load and a wall"]'::jsonb,3,'Pinch points can crush fingers.','original'),
('127.96.d.1.A',3,'A safe procedure before starting a repair on an existing building is to:','["Check for hazards like asbestos, lead paint, and live wires", "Start demolition immediately", "Remove warning signs", "Skip PPE"]'::jsonb,0,'Older buildings may hold hidden hazards.','original'),
('127.96.d.1.A',4,'When doing building maintenance in an occupied building, workers should:','["Leave tools in hallways", "Barricade the area and warn occupants", "Work without warning", "Block exits"]'::jsonb,1,'Protecting occupants is part of safe procedure.','original'),
('127.96.d.1.B',3,'OSHA was created to:','["Pay workers", "Draw plans", "Help ensure safe and healthful working conditions", "Sell tools"]'::jsonb,2,'OSHA sets and enforces standards.','original'),
('127.96.d.1.B',4,'On a maintenance crew, promoting on-site safety includes:','["Skipping briefings", "Ignoring rules", "Hiding hazards", "Reporting hazards and following posted rules"]'::jsonb,3,'Everyone helps promote safety.','original'),
('127.96.d.1.C',3,'A worksite hazard in a maintenance shop might be:','["Exposed blades on a table saw", "A labeled bin", "A closed cabinet", "A clean floor"]'::jsonb,0,'Missing guards are a hazard.','original'),
('127.96.d.1.C',4,'To minimize a slip hazard, a maintenance worker should:','["Ignore the spill", "Clean spills right away and post a warning", "Walk around it", "Cover it with a rag and leave"]'::jsonb,1,'Controls reduce hazards.','original'),
('127.96.d.1.D',3,'Supervisors have the obligation to:','["Hide accidents", "Avoid inspections", "Provide training and a safe worksite", "Skip training"]'::jsonb,2,'Employers must provide safety.','original'),
('127.96.d.1.D',4,'A worker''s safety obligation includes:','["Ignoring signs", "Working impaired", "Removing guards", "Following safe practices and using PPE"]'::jsonb,3,'Workers have duties too.','original'),
('127.96.d.1.E',3,'Accident costs include the injured worker''s pain and the employer''s:','["Lost productivity and higher insurance", "Faster work", "Lower taxes", "Extra tools"]'::jsonb,0,'Accidents are costly.','original'),
('127.96.d.1.E',4,'Investigating the cause of an accident helps to:','["Hide records", "Prevent it from happening again", "Delay the job", "Assign blame only"]'::jsonb,1,'Learning prevents repeats.','original'),
('127.96.d.1.F',3,'When using solvents and adhesives, ensure the area has:','["No exits", "Closed windows only", "Good ventilation", "No light"]'::jsonb,2,'Fumes can be harmful.','original'),
('127.96.d.1.F',4,'Hazardous chemicals should be kept in their:','["Food bottles", "Unmarked jars", "Open buckets", "Original labeled containers"]'::jsonb,3,'Labels carry hazard info.','original'),
('127.96.d.1.G',3,'Hearing protection is needed when working near:','["Loud power equipment", "Tape measures", "Books", "Quiet rooms"]'::jsonb,0,'Noise can damage hearing.','original'),
('127.96.d.1.G',4,'A dust mask or respirator protects the:','["Knees", "Lungs", "Feet", "Eyes"]'::jsonb,1,'Respiratory PPE filters air.','original'),
('127.96.d.1.H',3,'Lead-based paint is a particular concern in buildings built before:','["2005", "1995", "1978", "2010"]'::jsonb,2,'Lead paint was banned for homes in 1978.','original'),
('127.96.d.1.H',4,'If you suspect asbestos in old ceiling tile, you should:','["Burn it", "Sweep it dry", "Break it up", "Stop work and notify a supervisor"]'::jsonb,3,'Disturbing asbestos releases fibers.','original'),
('127.96.d.2.A',3,'A set of plans typically includes floor plans, elevations, sections, and:','["Details and schedules", "Receipts", "Menus", "Song lists"]'::jsonb,0,'These sheets show how to build.','original'),
('127.96.d.2.A',4,'The sheet that shows a building''s exterior sides is the:','["Door schedule", "Elevation", "Footing detail", "Plumbing riser"]'::jsonb,1,'Elevations show faces.','original'),
('127.96.d.2.B',3,'On a blueprint, a thick solid line usually shows:','["Center lines", "Hidden objects", "Visible object outlines", "Dimensions"]'::jsonb,2,'Line weights communicate meaning.','original'),
('127.96.d.2.B',4,'A long-short-long dashed line is typically used for a:','["Section cut", "Property line", "Wall edge", "Center line"]'::jsonb,3,'Center lines show symmetry.','original'),
('127.96.d.2.C',3,'A symbol showing a duplex receptacle is part of the:','["Electrical set", "Site grading", "Foundation", "Roof framing"]'::jsonb,0,'Electrical symbols mark outlets and switches.','original'),
('127.96.d.2.C',4,'A small circle with ''S'' next to a door often indicates a:','["Slab", "Switch", "Sink", "Stairs"]'::jsonb,1,'Check the legend for symbol meanings.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
